/// Checks that each id a create or update document for `documents` links
/// names a resource that exists, in the order the document was read.
async fn ontogen_document_check_linked(
    state: &AppState,
    linked: &OntogenDocumentLinkedIds,
) -> Result<(), OntogenErrorObject> {
    let store = state.store().await.map_err(ontogen_internal_error)?;
    if let Some(linked) = &linked.match_id {
        match doc::get_by_id(&store, &linked.id).await {
            Ok(_) => {}
            Err(crate::schema::AppError::DocNotFound(..)) => return Err(linked.not_found("docs")),
            Err(e) => return Err(ontogen_app_error(e)),
        }
    }
    if let Some(linked) = &linked.ref_id {
        match map::get_by_id(&store, &linked.id).await {
            Ok(_) => {}
            Err(crate::schema::AppError::MapNotFound(..)) => return Err(linked.not_found("maps")),
            Err(e) => return Err(ontogen_app_error(e)),
        }
    }
    if let Some(linked) = &linked.crate_id {
        match doc::get_by_id(&store, &linked.id).await {
            Ok(_) => {}
            Err(crate::schema::AppError::DocNotFound(..)) => return Err(linked.not_found("docs")),
            Err(e) => return Err(ontogen_app_error(e)),
        }
    }
    if let Some(linked) = &linked.self_id {
        match document::get_by_id(&store, &linked.id).await {
            Ok(_) => {}
            Err(crate::schema::AppError::DocumentNotFound(..)) => return Err(linked.not_found("documents")),
            Err(e) => return Err(ontogen_app_error(e)),
        }
    }
    if let Some(linked) = &linked.super_id {
        match map::get_by_id(&store, &linked.id).await {
            Ok(_) => {}
            Err(crate::schema::AppError::MapNotFound(..)) => return Err(linked.not_found("maps")),
            Err(e) => return Err(ontogen_app_error(e)),
        }
    }
    for linked in &linked.r#loop {
        match response::get_by_id(&store, &linked.id).await {
            Ok(_) => {}
            Err(crate::schema::AppError::ResponseNotFound(..)) => return Err(linked.not_found("responses")),
            Err(e) => return Err(ontogen_app_error(e)),
        }
    }
    Ok(())
}

