/// The `documents` resource `id` names, read as its `GET` reads it: the
/// parent of a relationship route.
async fn ontogen_document_read(state: &AppState, id: &OntogenLookupKey) -> Result<Document, OntogenErrorObject> {
    let store = state.store().await.map_err(ontogen_internal_error)?;
    document::get_by_id(&store, ontogen_document_lookup_key(id)?).await.map_err(ontogen_app_error)
}

/// Sets the relation field `field` of the `documents` resource `id` to
/// `value` through `document::update`, as a resource `PATCH` naming only that
/// relationship does.
async fn ontogen_document_write_field(
    state: &AppState,
    id: &str,
    field: &str,
    value: ::serde_json::Value,
) -> Result<(), OntogenErrorObject> {
    let input: UpdateDocumentInput = ontogen_from_fields(::serde_json::Map::from_iter([(field.to_owned(), value)]))?;
    let store = state.store().await.map_err(ontogen_internal_error)?;
    document::update(&store, id, input).await.map_err(ontogen_app_error)?;
    Ok(())
}

/// The `docs` resources `ids` name, in order, without the ids that
/// name none.
async fn ontogen_doc_fetch(state: &AppState, ids: &[String]) -> Result<Vec<Doc>, OntogenErrorObject> {
    let store = state.store().await.map_err(ontogen_internal_error)?;
    let mut found = Vec::with_capacity(ids.len());
    for id in ids {
        match doc::get_by_id(&store, id).await {
            Ok(entity) => found.push(entity),
            Err(crate::schema::AppError::DocNotFound(..)) => {}
            Err(e) => return Err(ontogen_app_error(e)),
        }
    }
    Ok(found)
}

/// Checks, in order, that each of `ids` names a resource of type `docs`.
async fn ontogen_doc_check_ids(state: &AppState, ids: &[OntogenLinkedId]) -> Result<(), OntogenErrorObject> {
    let store = state.store().await.map_err(ontogen_internal_error)?;
    for linked in ids {
        match doc::get_by_id(&store, &linked.id).await {
            Ok(_) => {}
            Err(crate::schema::AppError::DocNotFound(..)) => return Err(linked.not_found("docs")),
            Err(e) => return Err(ontogen_app_error(e)),
        }
    }
    Ok(())
}

