async fn ontogen_document_relationship_get(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    OntogenPath((id, rel)): OntogenPath<(OntogenLookupKey, OntogenLookupKey)>,
    OntogenRawQuery(ontogen_raw_query): OntogenRawQuery,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let ontogen_collection = "/api/documents";
    match rel.as_str() {
        Some("match") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/match"))
                .with_related(format!("{ontogen_base}/match"));
            let ontogen_data = OntogenLinkage::ToOne(
                ontogen_entity
                    .match_id
                    .as_ref()
                    .map(|ontogen_member| OntogenResourceIdentifier::new("docs", ontogen_member.as_str())),
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        Some("ref") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/ref"))
                .with_related(format!("{ontogen_base}/ref"));
            let ontogen_data = OntogenLinkage::ToOne(
                ontogen_entity
                    .ref_id
                    .as_ref()
                    .map(|ontogen_member| OntogenResourceIdentifier::new("maps", ontogen_member.as_str())),
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        Some("crate") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/crate"))
                .with_related(format!("{ontogen_base}/crate"));
            let ontogen_data = OntogenLinkage::ToOne(
                ontogen_entity
                    .crate_id
                    .as_ref()
                    .map(|ontogen_member| OntogenResourceIdentifier::new("docs", ontogen_member.as_str())),
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        Some("self") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/self"))
                .with_related(format!("{ontogen_base}/self"));
            let ontogen_data = OntogenLinkage::ToOne(
                ontogen_entity
                    .self_id
                    .as_ref()
                    .map(|ontogen_member| OntogenResourceIdentifier::new("documents", ontogen_member.as_str())),
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        Some("super") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/super"))
                .with_related(format!("{ontogen_base}/super"));
            let ontogen_data = OntogenLinkage::ToOne(
                ontogen_entity
                    .super_id
                    .as_ref()
                    .map(|ontogen_member| OntogenResourceIdentifier::new("maps", ontogen_member.as_str())),
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        Some("loop") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/loop"))
                .with_related(format!("{ontogen_base}/loop"));
            let ontogen_data = OntogenLinkage::ToMany(
                ontogen_entity
                    .r#loop
                    .iter()
                    .map(|ontogen_member| OntogenResourceIdentifier::new("responses", ontogen_member.as_str()))
                    .collect(),
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        _ => Err(::ontogen_jsonapi::error::no_such_relationship("documents", &rel)),
    }
}

async fn ontogen_document_relationship_patch(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    ontogen_path: Result<OntogenPath<(OntogenLookupKey, OntogenLookupKey)>, OntogenErrorObject>,
    ontogen_query: Result<OntogenQuery<OntogenNoParams>, OntogenErrorObject>,
    ontogen_body: OntogenBody,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let OntogenPath((id, rel)) = ontogen_path?;
    match rel.as_str() {
        Some("match") => {
            ontogen_query?;
            let ontogen_bytes = ontogen_body.into_bytes()?;
            let ontogen_linked = ::ontogen_jsonapi::request::to_one(
                &::ontogen_jsonapi::request::parse_relationship(&ontogen_bytes)?,
                "",
                "docs",
                true,
            )?
            .map(|ontogen_member| OntogenLinkedId { id: ontogen_member, pointer: "/data".to_owned() });
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            ontogen_doc_check_ids(&ontogen_state, ontogen_linked.as_slice()).await?;
            ontogen_document_write_field(
                &ontogen_state,
                &ontogen_entity.id,
                "match_id",
                ontogen_linked.map(|ontogen_member| ontogen_member.id).into(),
            )
            .await?;
            Ok(::ontogen_jsonapi::response::no_content())
        }
        Some("ref") => {
            ontogen_query?;
            let ontogen_bytes = ontogen_body.into_bytes()?;
            let ontogen_linked = ::ontogen_jsonapi::request::to_one(
                &::ontogen_jsonapi::request::parse_relationship(&ontogen_bytes)?,
                "",
                "maps",
                true,
            )?
            .map(|ontogen_member| OntogenLinkedId { id: ontogen_member, pointer: "/data".to_owned() });
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            ontogen_map_check_ids(&ontogen_state, ontogen_linked.as_slice()).await?;
            ontogen_document_write_field(
                &ontogen_state,
                &ontogen_entity.id,
                "ref_id",
                ontogen_linked.map(|ontogen_member| ontogen_member.id).into(),
            )
            .await?;
            Ok(::ontogen_jsonapi::response::no_content())
        }
        Some("crate") => {
            ontogen_query?;
            let ontogen_bytes = ontogen_body.into_bytes()?;
            let ontogen_linked = ::ontogen_jsonapi::request::to_one(
                &::ontogen_jsonapi::request::parse_relationship(&ontogen_bytes)?,
                "",
                "docs",
                true,
            )?
            .map(|ontogen_member| OntogenLinkedId { id: ontogen_member, pointer: "/data".to_owned() });
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            ontogen_doc_check_ids(&ontogen_state, ontogen_linked.as_slice()).await?;
            ontogen_document_write_field(
                &ontogen_state,
                &ontogen_entity.id,
                "crate_id",
                ontogen_linked.map(|ontogen_member| ontogen_member.id).into(),
            )
            .await?;
            Ok(::ontogen_jsonapi::response::no_content())
        }
        Some("self") => {
            ontogen_query?;
            let ontogen_bytes = ontogen_body.into_bytes()?;
            let ontogen_linked = ::ontogen_jsonapi::request::to_one(
                &::ontogen_jsonapi::request::parse_relationship(&ontogen_bytes)?,
                "",
                "documents",
                true,
            )?
            .map(|ontogen_member| OntogenLinkedId { id: ontogen_member, pointer: "/data".to_owned() });
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            ontogen_document_check_ids(&ontogen_state, ontogen_linked.as_slice()).await?;
            ontogen_document_write_field(
                &ontogen_state,
                &ontogen_entity.id,
                "self_id",
                ontogen_linked.map(|ontogen_member| ontogen_member.id).into(),
            )
            .await?;
            Ok(::ontogen_jsonapi::response::no_content())
        }
        Some("super") => {
            ontogen_query?;
            let ontogen_bytes = ontogen_body.into_bytes()?;
            let ontogen_linked = ::ontogen_jsonapi::request::to_one(
                &::ontogen_jsonapi::request::parse_relationship(&ontogen_bytes)?,
                "",
                "maps",
                true,
            )?
            .map(|ontogen_member| OntogenLinkedId { id: ontogen_member, pointer: "/data".to_owned() });
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            ontogen_map_check_ids(&ontogen_state, ontogen_linked.as_slice()).await?;
            ontogen_document_write_field(
                &ontogen_state,
                &ontogen_entity.id,
                "super_id",
                ontogen_linked.map(|ontogen_member| ontogen_member.id).into(),
            )
            .await?;
            Ok(::ontogen_jsonapi::response::no_content())
        }
        Some("loop") => {
            ontogen_query?;
            let ontogen_bytes = ontogen_body.into_bytes()?;
            let ontogen_linked = ::ontogen_jsonapi::request::to_many_linked(
                &::ontogen_jsonapi::request::parse_relationship(&ontogen_bytes)?,
                "",
                "responses",
                None,
            )?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            ontogen_response_check_ids(&ontogen_state, &ontogen_linked).await?;
            ontogen_document_write_field(
                &ontogen_state,
                &ontogen_entity.id,
                "loop",
                ontogen_linked.into_iter().map(|ontogen_member| ontogen_member.id).collect(),
            )
            .await?;
            Ok(::ontogen_jsonapi::response::no_content())
        }
        _ => Err(::ontogen_jsonapi::error::no_such_relationship("documents", &rel)),
    }
}

async fn ontogen_document_relationship_post(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    ontogen_path: Result<OntogenPath<(OntogenLookupKey, OntogenLookupKey)>, OntogenErrorObject>,
    ontogen_query: Result<OntogenQuery<OntogenNoParams>, OntogenErrorObject>,
    ontogen_body: OntogenBody,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let OntogenPath((id, rel)) = ontogen_path?;
    match rel.as_str() {
        Some("match") => {
            ontogen_query?;
            Err(::ontogen_jsonapi::error::relationship_update_unsupported("documents", "match", "POST"))
        }
        Some("ref") => {
            ontogen_query?;
            Err(::ontogen_jsonapi::error::relationship_update_unsupported("documents", "ref", "POST"))
        }
        Some("crate") => {
            ontogen_query?;
            Err(::ontogen_jsonapi::error::relationship_update_unsupported("documents", "crate", "POST"))
        }
        Some("self") => {
            ontogen_query?;
            Err(::ontogen_jsonapi::error::relationship_update_unsupported("documents", "self", "POST"))
        }
        Some("super") => {
            ontogen_query?;
            Err(::ontogen_jsonapi::error::relationship_update_unsupported("documents", "super", "POST"))
        }
        Some("loop") => {
            ontogen_query?;
            let ontogen_bytes = ontogen_body.into_bytes()?;
            let ontogen_linked = ::ontogen_jsonapi::request::to_many_linked(
                &::ontogen_jsonapi::request::parse_relationship(&ontogen_bytes)?,
                "",
                "responses",
                Some(1),
            )?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            ontogen_response_check_ids(&ontogen_state, &ontogen_linked).await?;
            if let Some(ontogen_ids) = ontogen_added(&ontogen_entity.r#loop, &ontogen_linked) {
                ontogen_document_write_field(&ontogen_state, &ontogen_entity.id, "loop", ontogen_ids.into()).await?;
            }
            Ok(::ontogen_jsonapi::response::no_content())
        }
        _ => Err(::ontogen_jsonapi::error::no_such_relationship("documents", &rel)),
    }
}

